<?php
require_once __DIR__.'/../../includes/inventory_service.php';requireRole('admin');
$start=$_GET['start']??date('Y-m-01');$end=$_GET['end']??date('Y-m-d');if(!parseTanggal($start)||!parseTanggal($end)||$start>$end){$start=date('Y-m-01');$end=date('Y-m-d');}
$summary=dbFetchOne($conn,"SELECT COUNT(*) total,COALESCE(SUM(CASE WHEN booking_status IN ('confirmed','ongoing','completed') THEN total_amount ELSE 0 END),0) nominal FROM bookings WHERE DATE(created_at) BETWEEN ? AND ?",'ss',[$start,$end]);
$payments=dbFetchOne($conn,"SELECT COALESCE(SUM(amount),0) nominal FROM payments WHERE payment_status='paid' AND DATE(COALESCE(verified_at,paid_at,created_at)) BETWEEN ? AND ?",'ss',[$start,$end]);
$items=dbFetchAll($conn,'SELECT e.equipment_name,e.stock_total,e.stock_unavailable,e.item_condition,c.category_name FROM equipment e JOIN categories c ON c.category_id=e.category_id ORDER BY c.category_name,e.equipment_name');
$damage=dbFetchAll($conn,'SELECT e.equipment_name,SUM(rd.quantity_damaged) damaged,SUM(rd.quantity_lost) lost FROM return_details rd JOIN equipment e ON e.equipment_id=rd.equipment_id JOIN returns r ON r.return_id=rd.return_id WHERE DATE(r.completed_at) BETWEEN ? AND ? GROUP BY rd.equipment_id,e.equipment_name HAVING damaged>0 OR lost>0','ss',[$start,$end]);
$bookings=dbFetchAll($conn,'SELECT booking_code,customer_name,booking_status,total_amount,created_at FROM bookings WHERE DATE(created_at) BETWEEN ? AND ? ORDER BY created_at DESC LIMIT 200','ss',[$start,$end]);
$panelTitle='Laporan';$activeMenu='laporan';$extraCss=['app-pages.css'];include __DIR__.'/../../includes/panel_header.php';?>
<div class="page-wrap"><h1>Laporan Inventaris & Transaksi</h1><?=flash_render()?>
<form method="get"><label>Awal</label><input type="date" name="start" value="<?=h($start)?>"><label>Akhir</label><input type="date" name="end" value="<?=h($end)?>"><button class="btn">Tampilkan</button></form>
<div class="card"><strong><?= (int)$summary['total']?> transaksi</strong> | Nilai booking terkonfirmasi/berjalan/selesai: <?=rupiah($summary['nominal'])?> | Pembayaran diterima: <?=rupiah($payments['nominal'])?><p class="muted">Pendapatan dummy berdasarkan status pembayaran, bukan laporan akuntansi final.</p></div>
<h2>Inventaris</h2><div class="table-scroll"><table class="tbl"><tr><th>Kategori</th><th>Barang</th><th>Total</th><th>Tidak tersedia</th><th>Kondisi</th></tr><?php foreach($items as $e):?><tr><td><?=h($e['category_name'])?></td><td><?=h($e['equipment_name'])?></td><td><?=(int)$e['stock_total']?></td><td><?=(int)$e['stock_unavailable']?></td><td><?=h($e['item_condition'])?></td></tr><?php endforeach;?></table></div>
<h2>Kerusakan & Kehilangan</h2><div class="table-scroll"><table class="tbl"><tr><th>Barang</th><th>Rusak</th><th>Hilang</th></tr><?php foreach($damage as $e):?><tr><td><?=h($e['equipment_name'])?></td><td><?=(int)$e['damaged']?></td><td><?=(int)$e['lost']?></td></tr><?php endforeach;?><?php if(!$damage):?><tr><td colspan="3">Tidak ada laporan pada periode ini.</td></tr><?php endif;?></table></div>
<h2>Transaksi</h2><div class="table-scroll"><table class="tbl"><tr><th>Booking</th><th>Customer</th><th>Status</th><th>Nilai</th><th>Dibuat</th></tr><?php foreach($bookings as $b):?><tr><td><?=h($b['booking_code'])?></td><td><?=h($b['customer_name'])?></td><td><?=h(label_status('booking',$b['booking_status']))?></td><td><?=rupiah($b['total_amount'])?></td><td><?=h($b['created_at'])?></td></tr><?php endforeach;?></table></div></div><?php include __DIR__.'/../../includes/panel_footer.php';?>
